CREATE COLUMN TABLE "TEST_AP"."SRA1" ("ActionCode" INTEGER CS_INT NOT NULL , "ParamCode" INTEGER CS_INT NOT NULL , "KeyString" NVARCHAR(32) NOT NULL , "KeyNumber" INTEGER CS_INT NOT NULL , "ValString" NCLOB MEMORY THRESHOLD 1000, "ValNumber" INTEGER CS_INT, "ValMoney" DECIMAL(21,6) CS_FIXED, PRIMARY KEY ("ActionCode", "ParamCode")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "SRA1_SECONDARY" ON "TEST_AP"."SRA1" ( "ActionCode" ASC, "KeyString" ASC, "KeyNumber" ASC )